#include <iostream>
#include <string>

class Persona {
public:
    std::string nombre;
    int edad;

    Persona(std::string n, int e) {
        nombre = n;
        edad = e;
    }
};

int main() {
    Persona p("María", 30);
    std::cout << p.nombre << "\n";
    std::cout << p.edad << "\n";
    return 0;
}
